// MARK: helpers

let repoRoot = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
    .deletingLastPathComponent()
let nativeSample = repoRoot.appendingPathComponent("re/out/native_save/GAME1.IM1")

func fileBytes(_ u: URL) throws -> [UInt8] { [UInt8](try Data(contentsOf: u)) }

func tempDir() -> URL {
    let u = FileManager.default.temporaryDirectory.appendingPathComponent("bioforge-save-" + UUID().uuidString)
    try? FileManager.default.createDirectory(at: u, withIntermediateDirectories: true)
    return u
}

/// The deterministic frame used for the writer parity values: a gradient over a synthetic palette.
func synthFrame() -> Framebuffer {
    var fb = Framebuffer()
    for i in 0..<256 { fb.palette[3 * i] = UInt8(i); fb.palette[3 * i + 1] = UInt8((i * 3) % 256); fb.palette[3 * i + 2] = UInt8(255 - i) }
    for y in 0..<200 { for x in 0..<320 { fb.pixels[y * 320 + x] = UInt8(((x / 6) + (y / 4) * 7) & 255) } }
    return fb
}

func sha256(_ s: String) -> String { sha(Array(s.utf8)) }

/// Compare a decoded SaveState with the Python-derived expectation.
func checkParity(_ st: SaveState, _ e: SaveExpect, _ label: String) throws {
    let m = st.misc
    #expect([m.saveName, m.level, m.camera] == [e.saveName, e.level, e.camera], "\(label) misc strings")
    let got: [Int] = [m.autoCamera, m.flag50bd, m.nextSerial, m.objA, m.objB], want: [Int] = [e.auto, e.flag50bd, e.nextSerial, e.objA, e.objB]
    #expect(got == want, "\(label) misc numbers")
    #expect(sha(m.serials.flatMap { [UInt8].le($0, 4) }) == e.serialsSha, "\(label) serials")
    let v = st.vars.items
    #expect(v.count == e.varsCount && "\(v[0].name)=\(v[0].value)" == e.varsFirst && "\(v.last!.name)=\(v.last!.value)" == e.varsLast, "\(label) vars")
    #expect(st.sounds.items.count == e.soundsCount)
    let ls = try st.lists.lists().map { l in l.name + "|" + l.items.map { "\($0.key),\($0.stamp)" }.joined(separator: ";") }
    #expect(sha256(ls.joined(separator: "\n")) == e.listsDigest, "\(label) lists")
    #expect(st.script.ident == e.ident)
    let slots = st.script.slots.map { s -> String in
        "\(s.index):\(s.kind.rawValue):\(s.className ?? "nil"):\(s.type):\(s.group):\(s.kind == .task || s.kind == .proc ? s.serial : 0)"
    }
    #expect(slots == e.slots, "\(label) slots")
    var n = 0
    for s in st.script.slots where s.kind == .proc {
        let p = try #require(try s.proc()), x = e.procs[n]; n += 1
        #expect(s.index == x.index && p.script == x.script && p.block == x.block && p.pc == x.pc && p.pc0 == x.pc0, "\(label) proc \(x.index)")
        let links: [Int] = [p.owner, p.objA, p.objB, p.curObj, p.waitSlot], want: [Int] = [x.owner, x.objA, x.objB, x.cur, x.wait]
        #expect(links == want, "\(label) proc \(x.index) links")
        #expect(p.l1 == x.l1 && p.l2 == x.l2 && p.locals == x.locals && p.objs == x.objs, "\(label) proc \(x.index) lists")
        #expect(p.encode() == s.b, "\(label) proc \(x.index) re-encode")
    }
    #expect(n == e.procs.count)
    let lv = try #require(st.levels[m.level.uppercased().replacingOccurrences(of: ".IFF", with: "")])
    #expect(lv.objects().count == e.levelObjects)
    var rows: [String] = []
    for (_, r) in try lv.records() {
        guard let r else { continue }
        func f(_ v: [Int]) -> String { "(" + v.map(String.init).joined(separator: ", ") + (v.count == 1 ? ",)" : ")") }
        func py(_ v: [Int]) -> String { "[" + v.map(String.init).joined(separator: ", ") + "]" }
        var row = "\(r.tag) \(r.name) \(r.inst) \(f(r.pos)) \(r.flags) \(r.holder) \(r.hand) \(r.hp) \(f(r.velocity)) \(py(r.locals))"
        if r.tag != "ITEM" {
            row += " " + String(format: "%.4f", r.heading) + " \(r.motion) \(r.enemy) \(r.motionTask) \(r.aiTask)"
            row += " [" + r.viewCams.map { "'\($0)'" }.joined(separator: ", ") + "]"
            row += " [" + r.avoid.map { "(\($0.waypoint), \($0.radius))" }.joined(separator: ", ") + "]"
            row += " " + r.inTrig.map { String(format: "%02x", $0) }.joined()
            if r.tag == "PLAY" { row += " \(r.playerClock) \(r.playerTarget)" }
        }
        rows.append(row)
    }
    #expect(rows.count == e.recCount)
    #expect(sha256(rows.joined(separator: "\n")) == e.recDigest, "\(label) ObjRec views")
}

@Suite(.enabled(if: game != nil, "BIOFORGE_DATA is not set; point it at the BioForge game folder"))
struct SaveGameTests {
    @Test func gamedatSiblingIsResolved() throws {
        let g = try requireGame()
        let u = try #require(g.gamedat)
        #expect(u.lastPathComponent.uppercased() == "GAMEDAT")
        #expect(FileManager.default.fileExists(atPath: u.appendingPathComponent("MISC.DAT").path))
        #expect(g.initgame?.lastPathComponent.uppercased() == "INITGAME")
    }

    @Test func gamedatEveryFileRoundTripsByteForByte() throws {
        let g = try requireGame(), dir = try #require(g.gamedat)
        let st = try SaveState.load(directory: dir)
        let enc = try st.files()
        let names = try FileManager.default.contentsOfDirectory(atPath: dir.path)
        #expect(names.count == 15 && enc.count == 15)
        for n in names { #expect(enc[n.uppercased()] == (try fileBytes(dir.appendingPathComponent(n))), "\(n)") }
        #expect(st.levels.count == 10)
        // write(to:) puts the same bytes back on disk
        let out = tempDir()
        defer { try? FileManager.default.removeItem(at: out) }
        try st.write(to: out.appendingPathComponent("play"))
        for n in names { #expect(try fileBytes(out.appendingPathComponent("play/" + n)) == (try fileBytes(dir.appendingPathComponent(n)))) }
    }

    @Test func initgameLevelsRoundTripByteForByte() throws {
        let dir = try #require(try requireGame().initgame)
        let names = try FileManager.default.contentsOfDirectory(atPath: dir.path).filter { $0.uppercased().hasSuffix(".IFF") }
        #expect(names.count == 10)
        for n in names {
            let raw = try fileBytes(dir.appendingPathComponent(n))
            let iff = try LevelIff.parse(raw)
            #expect(iff.encode() == raw, "\(n)")
            for (_, r) in try iff.records() { if let r { #expect(r.encode().count >= 191) } }
        }
    }

    @Test func gamedatMatchesPython() throws {
        let g = try requireGame(), dir = try #require(g.gamedat)
        let st = try SaveState.load(directory: dir, classNames: ClassNames(game: g))
        try checkParity(st, gamedatExpect, "GAMEDAT")
        let by = Dictionary(uniqueKeysWithValues: try st.script.slots.compactMap { s in try s.proc().map { (s.index, $0) } })
        for (i, name) in blockNames { #expect(by[i]?.blockName(in: g) == name, "slot \(i) block name") }
        #expect(st.describeObj(by[15]!.objA) == "PLAY LEX")
        #expect(st.script.kernelFields()["live_tasks"] == 25 && st.script.defines?.0 == 0x77e)
        #expect(st.script.activeList == [1, 3, 4, 5, 0x408])
    }

