    @Test func nativeIm1SampleRoundTripsAndMatchesPython() throws {
        guard FileManager.default.fileExists(atPath: nativeSample.path) else { return }   // optional local artifact
        let g = try requireGame()
        let data = try fileBytes(nativeSample)
        #expect(sha(data) == nativeIm1Sha)
        let flex = try SaveFlex.parse(data)
        #expect(try flex.encode() == data)
        let (ents, thumb, _) = try Im1.entries(data)
        #expect(sha(thumb) == nativeThumbSha)
        #expect(sha256(ents.map { "\($0.name),\($0.flag),\($0.originalSize)" }.joined(separator: ";")) == nativeEntriesDigest)
        #expect(ents.allSatisfy { $0.flag == 0 && $0.data.count == $0.originalSize })
        // the thumbnail is a CAM frame the encoder reproduces byte for byte
        let fr = try CAMImage.decodeFrame(thumb, at: 0)
        #expect((fr.width, fr.height, fr.hotX, fr.hotY) == (320, 200, 0, 0))
        #expect(try CAMImage.encodeFrame(width: 320, height: 200, pixels: fr.pixels) == thumb)

        let (files, names, thumb2) = try Im1.unpack(data)
        #expect(thumb2 == thumb && names == ents.map(\.name) && files.count == 15)
        // repacking reproduces it except the stale header word at 0x66
        var repacked = try Im1.pack(files: files, thumbnail: thumb)
        #expect(repacked.count == data.count)
        repacked[0x66] = data[0x66]; repacked[0x67] = data[0x67]
        #expect(repacked == data)

        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        try Im1.unpack(data, to: dir)
        #expect(try Im1.pack(directory: dir, thumbnail: thumb).count == data.count)
        let st = try SaveState.load(directory: dir, classNames: ClassNames(game: g))
        let enc = try st.files()
        for (n, b) in files { #expect(enc[n] == b, "\(n)") }
        try checkParity(st, nativeExpect, "GAME1.IM1")
    }

    @Test func im1PackUnpackIsSelfConsistent() throws {
        let files: [String: [UInt8]] = ["A.DAT": [1, 2, 3], "LONGNAME.IFF": [9], "B.DAT": []]
        let data = try Im1.pack(files: files, thumbnail: [7, 8])
        let f = try SaveFlex.parse(data)
        #expect(f.esz == "LONGNAME.IFF".count + 14 && f.entries.count == 4)
        #expect(f.hdr.starts(with: Im1.comment))
        let r = try Im1.unpack(data)
        #expect(r.files == files && r.thumbnail == [7, 8] && r.names == ["A.DAT", "B.DAT", "LONGNAME.IFF"])
        #expect(try Im1.pack(files: files, thumbnail: nil).starts(with: Array("(C) 1994 Origin Systems Inc.".utf8)))
        var bad = try SaveFlex.parse(data)
        bad.entries[1].tail[4] = 1
        #expect(throws: FormatError.self) { try Im1.unpack(try bad.encode()) }
    }

    @Test func camFrameEncoderRoundTripsWithAndWithoutMask() throws {
        var px = [UInt8](repeating: 0, count: 40 * 3), mask = px
        for i in 0..<px.count { px[i] = UInt8((i / 7) % 5); mask[i] = (i % 40 < 8 || i % 40 > 30 || i / 40 == 1 && i % 13 < 4) ? 0 : 1 }
        for rle in [true, false] {
            let b = try CAMImage.encodeFrame(width: 40, height: 3, pixels: px, hotX: 2, hotY: -1, rle: rle, mask: mask)
            let f = try CAMImage.decodeFrame(b, at: 0)
            #expect(f.mask == mask && (f.hotX, f.hotY) == (2, -1))
            #expect(zip(f.pixels, px).enumerated().allSatisfy { mask[$0.offset] == 0 || $0.element.0 == $0.element.1 })
        }
    }

    @Test func writerMatchesPython() throws {
        let g = try requireGame(), gamedat = try #require(g.gamedat), initgame = try #require(g.initgame)
        let frame = synthFrame()
        #expect(sha(try SaveWrite.thumbnail(frame)) == synthThumbSha)
        let lists = [LogList(name: "LEX", items: [LogItem(key: "MYBOOK", stamp: 100), LogItem(key: "X", stamp: 5)]),
                     LogList(name: "NEWL", items: [LogItem(key: "A", stamp: 1)]), LogList(name: "EMPTY", items: [])]
        let positions: [String: SIMD3<Double>] = [writerFigs.0: [100.4, -200.5, 300.5], writerFigs.1: [7.5, 8.5, -9.5], "LEX": [1, 2, 3]]
        let vars = ["_DIFFICULTY_LEVEL": 3, "NOSUCHVAR": 9]
        let out = tempDir()
        defer { try? FileManager.default.removeItem(at: out) }
        for (base, dir, expectFiles, expectIm1, label) in [
            (try SaveState.load(directory: gamedat) as SaveState?, gamedat, writeBaseFiles, writeBaseIm1, "native base"),
            (nil, initgame, writeFreshFiles, writeFreshIm1, "new game")] {
            let files = try SaveWrite.buildFiles(slotName: "GAME7.IM1", level: "CHAOS", camera: "CE11", autoCamera: true, variables: vars,
                                                 lists: lists, levelDir: dir, positions: positions, base: base, game: g)
            #expect(Set(files.keys) == Set(expectFiles.keys), "\(label) file names")
            for (n, b) in files { #expect(sha(b) == expectFiles[n], "\(label) \(n)") }
            let path = out.appendingPathComponent("sub/\(label.prefix(3)).IM1")
            try SaveWrite.writeIM1(to: path, files: files, frame: frame)
            #expect(sha(try fileBytes(path)) == expectIm1, "\(label) packed .IM1")
        }
    }

